# c305: 튜토리얼 바닥 화살표 — 가야 할 길을 따라 노란 세모
C305_R = [('    if (!chFog) {\n      for (const B of T) {', "    if (!chFog) {\n      { const by = (l) => buildings.find((q) => q.local === l), L = by(900), C1 = by(902), C2 = by(903), R2 = by(904), C3 = by(905), C4 = by(906), R3 = by(907), C5 = by(908), C6 = by(909), R4 = by(910), C7 = by(911);   // c305: 바닥 화살표 — 가야 할 길을 따라 노란 세모\n        const mx = (B) => (B.x0 + B.x1) / 2, mz = (B) => (B.z0 + B.z1) / 2, dX = L.locks[0].cx, R4d = R4.locks[0].cz, R2d = R2.locks[0].cz;\n        const P = [[L.x0 + 7.2, L.z0 + 4.6], [dX, L.z0 + 2.7], [dX, C1.z0 + 2.2], [C2.x1 - 1.2, mz(C2)], [R2.x0 + 1.4, mz(C2)], [R2.x1 - 1.4, R2d], [C3.x1 - 1.4, mz(C3)], [mx(C4), C4.z1 - 2.2], [mx(C4), C4.z0 + 1.2], [mx(C4), R3.z1 - 1.6], [mx(R3) - 0.6, mz(R3)], [mx(C5), R3.z0 + 2.4], [mx(C5), C5.z0 + 2.2], [C6.x1 - 1.4, mz(C6)], [R4.x0 + 1.4, mz(C6)], [R4.x1 - 1.4, R4d], [C7.x0 + 6.4, mz(C7)]];\n        const tex = chTexOf(96, 96, (g) => { g.beginPath(); g.moveTo(84, 48); g.lineTo(18, 12); g.lineTo(34, 48); g.lineTo(18, 84); g.closePath(); g.lineJoin = 'round'; g.lineWidth = 8; g.strokeStyle = 'rgba(40,30,0,0.85)'; g.stroke(); g.fillStyle = '#ffd34d'; g.fill(); });\n        const mat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, opacity: 0.92, depthTest: false, depthWrite: false }), geo = new THREE.PlaneGeometry(1.2, 1.2).rotateX(-Math.PI / 2);\n        for (let i = 0; i + 1 < P.length; i++) { const [ax, az] = P[i], [bx, bz] = P[i + 1], dx = bx - ax, dz = bz - az, d = Math.hypot(dx, dz), n = Math.max(1, Math.floor(d / 3.5));\n          for (let k = 0; k < n; k++) { const t = (k + 0.5) / n, m = new THREE.Mesh(geo, mat); m.position.set(ax + dx * t, 0.025, az + dz * t); m.rotation.y = Math.atan2(-dz, dx); m.renderOrder = -0.59; scene.add(m); } } }\n      for (const B of T) {")]
